'use strict';
const en=document.documentElement.lang==='en';
const tr=(fr,eng)=>en?eng:fr;
const menu=document.querySelector('.menu-toggle');
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));document.querySelector('#mobile-menu').hidden=!open;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu?.getAttribute('aria-expanded')==='true'){menu.click();menu.focus();}});
const reduce=matchMedia('(prefers-reduced-motion: reduce)');
const limited=navigator.connection?.saveData||['slow-2g','2g'].includes(navigator.connection?.effectiveType);
const vids=[...document.querySelectorAll('[data-video]')];
vids.forEach(v=>{const parent=v.closest('.hero,.wide-film,.image-wrap');const b=parent?.querySelector('[data-video-toggle]');const update=()=>{if(!b)return;b.textContent=v.paused?tr('Lire la vidéo','Play video'):tr('Mettre en pause','Pause video');b.setAttribute('aria-pressed',String(!v.paused));};v.addEventListener('play',update);v.addEventListener('pause',update);v.addEventListener('error',()=>{v.removeAttribute('src');v.load();if(b){b.textContent=tr('Vidéo indisponible','Video unavailable');b.disabled=true;}});b?.addEventListener('click',()=>{if(!v.src)v.src=v.dataset.src;if(v.paused){v.dataset.userPaused='false';v.play().catch(update);}else{v.dataset.userPaused='true';v.pause();}});});
function startSmooth(v){if(v.readyState>=4){v.play().catch(()=>{});return;}if(v.dataset.waitPlay)return;v.dataset.waitPlay='1';v.preload='auto';v.addEventListener('canplaythrough',()=>{delete v.dataset.waitPlay;const r=v.getBoundingClientRect();if(v.dataset.userPaused!=='true'&&!document.hidden&&r.bottom>0&&r.top<innerHeight)v.play().catch(()=>{});},{once:true});}
const videoObserver=new IntersectionObserver(entries=>{for(const {target:v,isIntersecting} of entries){if(!isIntersecting){v.pause();continue;}if(!reduce.matches&&!limited&&v.dataset.userPaused!=='true'){if(!v.src)v.src=v.dataset.src;startSmooth(v);}}},{threshold:.15});vids.forEach(v=>videoObserver.observe(v));reduce.addEventListener('change',()=>{if(reduce.matches)vids.forEach(v=>v.pause());});document.addEventListener('visibilitychange',()=>{if(document.hidden)vids.forEach(v=>v.pause());});
if(!reduce.matches&&'IntersectionObserver'in window){document.body.classList.add('js-motion');const reveal=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');reveal.unobserve(e.target);}}),{threshold:.06});document.querySelectorAll('.reveal').forEach(e=>reveal.observe(e));}
if(matchMedia('(pointer:fine)').matches&&!reduce.matches){document.querySelectorAll('.service-card .image-wrap').forEach(el=>{el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect();el.style.transform=`perspective(1100px) rotateY(${(e.clientX-r.left-r.width/2)/r.width*1.3}deg)`;});el.addEventListener('pointerleave',()=>el.style.transform='');});}
const cookie=document.querySelector('#cookie-dialog');document.querySelectorAll('[data-cookie-open]').forEach(b=>b.addEventListener('click',()=>cookie.showModal()));document.querySelector('[data-cookie-close]')?.addEventListener('click',()=>cookie.close());document.querySelectorAll('[data-cookie-choice]').forEach(b=>b.addEventListener('click',()=>{try{localStorage.setItem('codem-privacy',b.dataset.cookieChoice);}catch{}cookie.close();}));
const HOME=en?'/en/':'/fr/';const PHONE='01 71 36 18 38';
const todayISO=(()=>{const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10);})();
document.querySelectorAll('[data-min-today]').forEach(i=>i.min=todayISO);
function fieldLabel(el){return (el.closest('.field')?.querySelector('label')?.textContent||el.closest('label')?.textContent||el.name||'').replace(/\s*\*\s*$/,'').trim();}
function setError(el,msg){el.setAttribute('aria-invalid',msg?'true':'false');const err=el.closest('.field')?.querySelector('.field-error')||document.getElementById(el.name+'-error');if(err)err.textContent=msg||'';}
function validate(scope){const problems=[];const seen=new Set();scope.querySelectorAll('input,select,textarea').forEach(el=>{if(el.disabled||el.closest('[hidden]')||el.type==='hidden'||el.type==='file'||el.name==='website')return;if(el.type==='radio'){if(!el.required||seen.has(el.name))return;seen.add(el.name);if(!scope.querySelector(`[name="${el.name}"]:checked`)){const m=tr('Choisissez une option.','Please choose an option.');setError(el,m);problems.push({el,label:el.closest('fieldset')?.querySelector('legend')?.textContent||el.name,msg:m});}else setError(el,'');return;}if(el.type==='checkbox'){if(el.required&&!el.checked){const m=tr('Cette case doit être cochée.','This box must be ticked.');setError(el,m);problems.push({el,label:fieldLabel(el),msg:m});}else if(el.required)setError(el,'');return;}const ok=el.checkValidity();const m=ok?'':el.validity.valueMissing?tr('Veuillez compléter ce champ.','Please complete this field.'):tr('Veuillez vérifier cette information.','Please check this information.');setError(el,m);if(!ok)problems.push({el,label:fieldLabel(el),msg:m});});return problems;}
function contactRule(form,problems){const email=form.querySelector('[name="email"]'),tel=form.querySelector('[name="telephone"]'),canal=form.querySelector('[name="canal"],[name="preference"]');if(!email||!tel)return problems;const want=canal?.value;if(!email.value.trim()&&!tel.value.trim()){const m=tr('Indiquez un e-mail ou un téléphone.','Enter an email or a phone number.');setError(tel,m);problems.push({el:tel,label:fieldLabel(tel),msg:m});}else if(want==='email'&&!email.value.trim()){const m=tr('Indiquez votre e-mail.','Enter your email.');setError(email,m);problems.push({el:email,label:fieldLabel(email),msg:m});}else if(want==='telephone'&&!tel.value.trim()){const m=tr('Indiquez votre téléphone.','Enter your phone number.');setError(tel,m);problems.push({el:tel,label:fieldLabel(tel),msg:m});}return problems;}
async function transmit(form,data){const ep=form.dataset.endpoint;if(!ep)return 'offline';const r=await fetch(ep,{method:'POST',body:data,headers:{'Accept':'application/json'}});if(!r.ok)throw new Error('send');return 'sent';}
const notActive=()=>tr(`L’envoi en ligne n’est pas encore activé sur ce site. Pour transmettre votre demande dès maintenant, appelez le ${PHONE}.`,`Online sending is not active on this site yet. To pass on your request now, call +33 1 71 36 18 38.`);
document.querySelectorAll('form').forEach(form=>form.addEventListener('input',e=>{if(e.target.matches('input,textarea,select'))setError(e.target,'');}));
document.querySelectorAll('#callback-form,#visit-form,#contact-form').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const status=form.querySelector('.form-status');status.classList.remove('ok');let problems=validate(form);if(form.id==='contact-form')problems=contactRule(form,problems);if(problems.length){problems[0].el.focus();return;}try{const res=await transmit(form,new FormData(form));status.classList.add('ok');status.textContent=res==='sent'?tr('Merci, votre demande a bien été envoyée. Un conseiller CODEM vous recontacte.','Thank you, your request has been sent. A CODEM adviser will contact you.'):notActive();}catch{status.textContent=tr(`L’envoi a échoué. Réessayez ou appelez le ${PHONE}.`,'Sending failed. Please try again or call +33 1 71 36 18 38.');}}));

// Devis en 9 étapes
const quote=document.querySelector('#quote-form');
if(quote){
 const steps=[...quote.querySelectorAll('.qstep')],navs=[...document.querySelectorAll('.quote-steps li')];
 const next=quote.querySelector('[data-next]'),prev=quote.querySelector('[data-prev]'),send=quote.querySelector('[data-submit]'),actionsBar=quote.querySelector('.quote-actions');
 const errBox=quote.querySelector('.error-summary'),KEY='codem-quote-v2';let step=0;
 const apply=data=>{for(const [k,vals] of Object.entries(data)){quote.querySelectorAll(`[name="${k}"]`).forEach(el=>{if(el.type==='file')return;if(el.type==='checkbox'||el.type==='radio')el.checked=vals.includes(el.value);else el.value=vals[0]??'';});}};
 const collect=()=>{const d={};new FormData(quote).forEach((v,k)=>{if(typeof v!=='string'||k==='website')return;(d[k]??=[]).push(v);});return d;};
 const save=()=>{try{localStorage.setItem(KEY,JSON.stringify({step,data:collect()}));}catch{}};
 const modeSync=()=>{const m=quote.querySelector('[name="volume_mode"]:checked')?.value||'surface';quote.querySelectorAll('[data-mode]').forEach(b=>b.hidden=b.dataset.mode!==m);};
 try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s?.data){apply(s.data);step=Math.min(Math.max(s.step||0,0),7);}}catch{}
 const params=new URLSearchParams(location.search);
 if([...params.keys()].length){const d={},map={service:'projet',depart:'depart_commune',arrivee:'arrivee_commune',date:'date',logement:'depart_type',taille:'taille',formule:'formule',pays:'arrivee_pays',depart_pays:'depart_pays',objets:'objets',surface:'surface',volume:'volume',etage:'depart_etage',annexes:'annexes',organisation:'organisation',contraintes:'contraintes'};for(const [p,f] of Object.entries(map)){const v=params.get(p);if(v)d[f]=[v];}const a=params.get('acces');if(a==='ascenseur')d.depart_ascenseur=['oui'];if(a==='escalier')d.depart_ascenseur=['non'];if(a==='a-verifier')d.depart_ascenseur=['a-verifier'];if(a==='monte-meubles')d.prestations=['monte-meubles'];const pr=params.getAll('prestation');if(pr.length)d.prestations=[...new Set([...(d.prestations||[]),...pr])];if(params.get('volume'))d.volume_mode=['volume'];if(params.get('groupage'))d.groupage=['oui'];apply(d);step=d.projet&&d.depart_commune&&d.arrivee_commune?2:d.projet?1:0;history.replaceState(null,'',location.pathname);}
 const showErrors=problems=>{const ul=errBox.querySelector('ul');ul.replaceChildren();problems.forEach(p=>{const li=document.createElement('li');li.textContent=(p.label?`${p.label} : `:'')+p.msg;ul.append(li);});errBox.hidden=!problems.length;if(problems.length){errBox.scrollIntoView({behavior:'smooth',block:'center'});problems[0].el.focus({preventScroll:true});}};
 const show=(focus=true)=>{steps.forEach((s,i)=>s.hidden=i!==step);navs.forEach((li,i)=>{li.classList.toggle('done',i<step);if(i===step)li.setAttribute('aria-current','step');else li.removeAttribute('aria-current');});document.querySelector('[data-step-num]').textContent=step+1;quote.querySelector('.progress-bar').style.width=`${(step+1)/9*100}%`;prev.textContent=step===0?tr('Quitter','Exit'):tr('← Retour','← Back');next.hidden=step>=7;send.hidden=step!==7;actionsBar.hidden=step===8;errBox.hidden=true;modeSync();if(focus){steps[step].querySelector('h2').focus({preventScroll:true});window.scrollTo({top:quote.getBoundingClientRect().top+scrollY-110,behavior:'smooth'});}};
 const check=()=>{let p=validate(steps[step]);if(step===7)p=contactRule(steps[step],p);showErrors(p);return !p.length;};
 next.addEventListener('click',()=>{if(!check())return;step++;save();show();});
 prev.addEventListener('click',()=>{if(step===0){save();location.href=HOME;return;}step--;save();show();});
 quote.addEventListener('change',e=>{if(e.target.name==='volume_mode')modeSync();if(e.target.name==='projet'&&step===0){save();}save();});
 quote.addEventListener('input',()=>save());
 const label=name=>{const el=quote.querySelector(`[name="${name}"]:checked`);if(el)return el.closest('label').querySelector('.choice-title')?.textContent||el.value;const s=quote.querySelector(`select[name="${name}"]`);return s&&s.value?s.selectedOptions[0].textContent:'';};
 const val=n=>quote.querySelector(`[name="${n}"]`)?.value.trim()||'';
 const summary=()=>{const box=quote.querySelector('[data-summary]');box.replaceChildren();const d=val('date');const date=d?new Date(d+'T12:00').toLocaleDateString(en?'en-GB':'fr-FR',{day:'numeric',month:'long',year:'numeric'}):tr('À définir','To be decided');const rows=[[tr('Projet','Project'),label('projet')],[tr('Trajet','Route'),`${val('depart_commune')} → ${val('arrivee_commune')}`],[tr('Date','Date'),date],[tr('Contact','Contact'),label('canal')||val('telephone')||val('email')]];rows.forEach(([k,v])=>{const div=document.createElement('div'),s=document.createElement('small'),st=document.createElement('strong');s.textContent=k;st.textContent=v||'—';div.append(s,st);box.append(div);});};
 quote.addEventListener('submit',async e=>{e.preventDefault();if(!check())return;const ref='CDM-'+todayISO.replace(/-/g,'').slice(2)+'-'+Math.random().toString(36).slice(2,6).toUpperCase();const fd=new FormData(quote);fd.append('reference',ref);const status=quote.querySelector('.form-status');send.disabled=true;try{const res=await transmit(quote,fd);quote.querySelector('[data-ref]').textContent=ref;summary();if(res==='sent'){quote.querySelector('[data-confirm-title]').textContent=tr('Votre demande est envoyée','Your request has been sent');quote.querySelector('[data-confirm-text]').textContent=tr('Un conseiller CODEM étudie votre projet et vous recontacte sur le créneau choisi. Un récapitulatif vous est adressé par e-mail.','A CODEM adviser is reviewing your move and will contact you at your chosen time. A summary is on its way by email.');try{localStorage.removeItem(KEY);}catch{}}else{quote.querySelector('[data-confirm-text]').textContent=notActive()+' '+tr('Indiquez votre numéro de demande : vos réponses restent enregistrées sur cet appareil.','Quote your request number: your answers stay saved on this device.');}step=8;show();status.textContent='';}catch{status.textContent=tr(`L’envoi a échoué. Réessayez ou appelez le ${PHONE}.`,'Sending failed. Please try again or call +33 1 71 36 18 38.');}finally{send.disabled=false;}});
 show(false);
}

// The floating navigation becomes opaque as content passes beneath it.
const premiumHeader=document.querySelector('header');
const updateHeader=()=>premiumHeader?.classList.toggle('scrolled',window.scrollY>40);
window.addEventListener('scroll',updateHeader,{passive:true});updateHeader();
// Each service has its own description, photograph and destination link.
const expertiseButtons=[...document.querySelectorAll('[data-service-index]')];
expertiseButtons.forEach(button=>button.addEventListener('click',()=>{
  const selected=button.dataset.serviceIndex;
  expertiseButtons.forEach(item=>{
    const active=item.dataset.serviceIndex===selected;
    item.setAttribute('aria-expanded',String(active));
    document.getElementById(item.getAttribute('aria-controls')).hidden=!active;
  });
  document.querySelectorAll('[data-service-visual]').forEach(visual=>visual.hidden=visual.dataset.serviceVisual!==selected);
}));
